use clap::Parser;
use regex::Regex;
use std::fs;
use std::io::{self, BufRead, BufReader, Read};
use std::path::PathBuf;
use std::collections::HashSet;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(about = "A log file highlighter")]
struct Args {
    /// Filepath
    #[arg(value_name = "FILE")]
    file: Option<PathBuf>,

    /// Follow the contents of a file
    #[arg(short, long)]
    follow: bool,

    /// Print the output to stdout
    #[arg(short, long)]
    print: bool,

    /// Provide a custom path to a configuration file
    #[arg(long)]
    config_path: Option<PathBuf>,

    /// Run command and view the output in a pager
    #[arg(short, long)]
    exec: Option<String>,

    /// Highlights in the form color:word1,word2
    #[arg(long)]
    highlight: Vec<String>,

    /// Enable specific highlighters
    #[arg(long)]
    enable: Option<String>,

    /// Disable specific highlighters
    #[arg(long)]
    disable: Option<String>,

    /// Disable the highlighting of all builtin keyword groups
    #[arg(long)]
    disable_builtin_keywords: bool,

    /// Override the default pager command
    #[arg(long, env = "TAILSPIN_PAGER")]
    pager: Option<String>,
}

#[derive(Clone)]
struct Highlighter {
    patterns: Vec<(Regex, String, String)>, // (pattern, color_code, reset_code)
}

impl Highlighter {
    fn new(
        enable: Option<HashSet<String>>,
        disable: Option<HashSet<String>>,
        disable_builtins: bool,
        custom_highlights: Vec<(String, Vec<String>)>,
    ) -> Self {
        let mut patterns = Vec::new();

        // Determine which highlighters to enable
        let all_highlighters = vec![
            "numbers", "urls", "pointers", "dates", "paths",
            "quotes", "key-value-pairs", "uuids", "ip-addresses",
            "processes", "json"
        ];

        let should_enable = |name: &str| -> bool {
            if let Some(ref enabled) = enable {
                enabled.contains(name)
            } else if let Some(ref disabled) = disable {
                !disabled.contains(name)
            } else {
                true
            }
        };

        if !disable_builtins {
            // Log levels
            if should_enable("numbers") {
                patterns.push((
                    Regex::new(r"\bERROR\b").unwrap(),
                    "\x1b[31m".to_string(),
                    "\x1b[0m".to_string(),
                ));
                patterns.push((
                    Regex::new(r"\bWARN\b").unwrap(),
                    "\x1b[33m".to_string(),
                    "\x1b[0m".to_string(),
                ));
                patterns.push((
                    Regex::new(r"\bINFO\b").unwrap(),
                    "\x1b[37m".to_string(),
                    "\x1b[0m".to_string(),
                ));
                patterns.push((
                    Regex::new(r"\bDEBUG\b").unwrap(),
                    "\x1b[32m".to_string(),
                    "\x1b[0m".to_string(),
                ));
                patterns.push((
                    Regex::new(r"\bTRACE\b").unwrap(),
                    "\x1b[2m".to_string(),
                    "\x1b[0m".to_string(),
                ));
            }

            // Booleans and null
            patterns.push((
                Regex::new(r"\b(true|false|null)\b").unwrap(),
                "\x1b[3;31m".to_string(),
                "\x1b[0m".to_string(),
            ));

            // REST verbs
            patterns.push((
                Regex::new(r"\b GET\b").unwrap(),
                "\x1b[42;30m GET \x1b[0m".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\b POST\b").unwrap(),
                "\x1b[43;30m POST \x1b[0m".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\b PUT\b").unwrap(),
                "\x1b[45;30m PUT \x1b[0m".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\b DELETE\b").unwrap(),
                "\x1b[41;30m DELETE \x1b[0m".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\b PATCH\b").unwrap(),
                "\x1b[45;30m PATCH \x1b[0m".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\bTRACE\b").unwrap(),
                "\x1b[2m".to_string(),
                "\x1b[0m".to_string(),
            ));

            // SUCCESS
            patterns.push((
                Regex::new(r"\bSUCCESS\b").unwrap(),
                "\x1b[32m".to_string(),
                "\x1b[0m".to_string(),
            ));
        }

        // Numbers
        if should_enable("numbers") {
            patterns.push((
                Regex::new(r"\b\d+\b").unwrap(),
                "\x1b[36m".to_string(),
                "\x1b[0m".to_string(),
            ));
        }

        // UUIDs
        if should_enable("uuids") {
            patterns.push((
                Regex::new(r"\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b").unwrap(),
                "UUID_SPECIAL".to_string(),
                "".to_string(),
            ));
        }

        // IP addresses
        if should_enable("ip-addresses") {
            patterns.push((
                Regex::new(r"\b(?:\d{1,3}\.){3}\d{1,3}\b").unwrap(),
                "IP_SPECIAL".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\b(?:[0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}\b").unwrap(),
                "IPV6_SPECIAL".to_string(),
                "".to_string(),
            ));
        }

        // URLs
        if should_enable("urls") {
            patterns.push((
                Regex::new(r"\b(https?)://[^\s]+").unwrap(),
                "URL_SPECIAL".to_string(),
                "".to_string(),
            ));
            patterns.push((
                Regex::new(r"\bftp://\S+").unwrap(),
                "FTP_SPECIAL".to_string(),
                "".to_string(),
            ));
        }

        // Dates
        if should_enable("dates") {
            patterns.push((
                Regex::new(r"\b\d{4}[-/]\d{2}[-/]\d{2}\b").unwrap(),
                "DATE_SPECIAL".to_string(),
                "".to_string(),
            ));
        }

        // Paths
        if should_enable("paths") {
            patterns.push((
                Regex::new(r"(/[\w./_-]+)+").unwrap(),
                "PATH_SPECIAL".to_string(),
                "".to_string(),
            ));
        }

        // Quotes (double quotes)
        if should_enable("quotes") {
            patterns.push((
                Regex::new(r#""[^"]*""#).unwrap(),
                "\x1b[33m".to_string(),
                "\x1b[0m".to_string(),
            ));
        }

        // JSON
        if should_enable("json") {
            patterns.push((
                Regex::new(r#""[^"]*"(?=\s*:)"#).unwrap(),
                "\x1b[33m".to_string(),
                "\x1b[0m".to_string(),
            ));
        }

        // Add custom highlights
        for (color, words) in custom_highlights {
            for word in words {
                let color_code = match color.as_str() {
                    "red" => "\x1b[31m".to_string(),
                    "green" => "\x1b[32m".to_string(),
                    "yellow" => "\x1b[33m".to_string(),
                    "blue" => "\x1b[34m".to_string(),
                    "magenta" => "\x1b[35m".to_string(),
                    "cyan" => "\x1b[36m".to_string(),
                    _ => continue,
                };
                if let Ok(regex) = Regex::new(&format!(r"\b{}\b", regex::escape(&word))) {
                    patterns.push((
                        regex,
                        color_code,
                        "\x1b[0m".to_string(),
                    ));
                }
            }
        }

        Highlighter { patterns }
    }

    fn highlight_line(&self, line: &str) -> String {
        let mut result = String::new();
        let mut last_end = 0;

        // Collect all matches
        let mut matches: Vec<(usize, usize, usize)> = Vec::new();
        for (idx, (regex, _, _)) in self.patterns.iter().enumerate() {
            if let Some(m) = regex.find(line) {
                matches.push((m.start(), m.end(), idx));
            }
        }

        if matches.is_empty() {
            return line.to_string();
        }

        // Sort by start position
        matches.sort_by_key(|m| m.0);

        for (start, end, pattern_idx) in matches {
            if start >= last_end {
                result.push_str(&line[last_end..start]);
                let (_, color, reset) = &self.patterns[pattern_idx];

                let matched_text = &line[start..end];
                if color == "UUID_SPECIAL" {
                    result.push_str(&self.highlight_uuid(matched_text));
                } else if color == "IP_SPECIAL" {
                    result.push_str(&self.highlight_ip(matched_text));
                } else if color == "IPV6_SPECIAL" {
                    result.push_str(&self.highlight_ipv6(matched_text));
                } else if color == "URL_SPECIAL" {
                    result.push_str(&self.highlight_url(matched_text));
                } else if color == "FTP_SPECIAL" {
                    result.push_str(&self.highlight_ftp(matched_text));
                } else if color == "DATE_SPECIAL" {
                    result.push_str(&self.highlight_date(matched_text));
                } else if color == "PATH_SPECIAL" {
                    result.push_str(&self.highlight_path(matched_text));
                } else {
                    result.push_str(color);
                    result.push_str(matched_text);
                    result.push_str(reset);
                }
                last_end = end;
            }
        }

        result.push_str(&line[last_end..]);
        result
    }

    fn highlight_uuid(&self, uuid: &str) -> String {
        let mut result = String::new();
        for (i, c) in uuid.chars().enumerate() {
            if c == '-' {
                result.push_str("\x1b[31m-\x1b[0m");
            } else if c.is_ascii_hexdigit() {
                if c.is_ascii_lowercase() || (c.is_ascii_uppercase() && c < 'F') {
                    result.push_str("\x1b[3;35m");
                } else {
                    result.push_str("\x1b[3;34m");
                }
                result.push(c);
                result.push_str("\x1b[0m");
            } else {
                result.push(c);
            }
        }
        result
    }

    fn highlight_ip(&self, ip: &str) -> String {
        let mut result = String::new();
        for (i, part) in ip.split('.').enumerate() {
            if i > 0 {
                result.push_str("\x1b[31m.\x1b[0m");
            }
            result.push_str("\x1b[3;34m");
            result.push_str(part);
            result.push_str("\x1b[0m");
        }
        result
    }

    fn highlight_ipv6(&self, ip: &str) -> String {
        let mut result = String::new();
        for (i, part) in ip.split(':').enumerate() {
            if i > 0 {
                result.push_str("\x1b[31m:\x1b[0m");
            }
            for c in part.chars() {
                if c.is_ascii_hexdigit() {
                    if c.is_ascii_lowercase() || (c.is_ascii_uppercase() && c < 'F') {
                        result.push_str("\x1b[3;35m");
                    } else {
                        result.push_str("\x1b[3;34m");
                    }
                    result.push(c);
                    result.push_str("\x1b[0m");
                } else {
                    result.push(c);
                }
            }
        }
        result
    }

    fn highlight_url(&self, url: &str) -> String {
        let mut result = String::new();
        if let Some(pos) = url.find("://") {
            let scheme = &url[..pos];
            let rest = &url[pos + 3..];

            if scheme == "http" {
                result.push_str("\x1b[2;31mhttp\x1b[0m");
            } else if scheme == "https" {
                result.push_str("\x1b[2;32mhttps\x1b[0m");
            } else {
                result.push_str(scheme);
            }

            result.push_str("://");

            if let Some(slash_pos) = rest.find('/') {
                let domain = &rest[..slash_pos];
                let path = &rest[slash_pos..];
                result.push_str("\x1b[2;34m");
                result.push_str(domain);
                result.push_str("\x1b[0m\x1b[34m");
                result.push_str(path);
                result.push_str("\x1b[0m");
            } else {
                result.push_str("\x1b[2;34m");
                result.push_str(rest);
                result.push_str("\x1b[0m");
            }
        } else {
            result.push_str(url);
        }
        result
    }

    fn highlight_ftp(&self, ftp: &str) -> String {
        ftp.to_string()
    }

    fn highlight_date(&self, date: &str) -> String {
        let mut result = String::new();
        for (i, part) in date.split(|c| c == '-' || c == '/').enumerate() {
            if i > 0 {
                if date.contains('-') {
                    result.push_str("\x1b[2m-\x1b[0m");
                } else {
                    result.push_str("\x1b[2m/\x1b[0m");
                }
            }
            result.push_str("\x1b[35m");
            result.push_str(part);
            result.push_str("\x1b[0m");
        }
        result
    }

    fn highlight_path(&self, path: &str) -> String {
        let mut result = String::new();
        for (i, part) in path.split('/').enumerate() {
            if i > 0 {
                result.push_str("\x1b[33m/\x1b[0m");
            }
            if !part.is_empty() {
                result.push_str("\x1b[32m");
                result.push_str(part);
                result.push_str("\x1b[0m");
            }
        }
        result
    }
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    if args.file.is_none() && args.exec.is_none() {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();

        // Parse enable/disable
        let enable = args.enable.as_ref().map(|e| {
            e.split(',')
                .map(|s| s.trim().to_string())
                .collect::<HashSet<_>>()
        });

        let disable = args.disable.as_ref().map(|d| {
            d.split(',')
                .map(|s| s.trim().to_string())
                .collect::<HashSet<_>>()
        });

        // Parse custom highlights
        let mut custom_highlights = Vec::new();
        for highlight in &args.highlight {
            if let Some((color, words_str)) = highlight.split_once(':') {
                let words: Vec<String> = words_str
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .collect();
                custom_highlights.push((color.to_string(), words));
            }
        }

        let highlighter = Highlighter::new(enable, disable, args.disable_builtin_keywords, custom_highlights);

        for line in reader.lines() {
            let line = line?;
            println!("{}", highlighter.highlight_line(&line));
        }
    } else if let Some(file_path) = args.file {
        // Read from file
        let file = fs::File::open(&file_path)?;
        let reader = BufReader::new(file);

        // Parse enable/disable
        let enable = args.enable.as_ref().map(|e| {
            e.split(',')
                .map(|s| s.trim().to_string())
                .collect::<HashSet<_>>()
        });

        let disable = args.disable.as_ref().map(|d| {
            d.split(',')
                .map(|s| s.trim().to_string())
                .collect::<HashSet<_>>()
        });

        // Parse custom highlights
        let mut custom_highlights = Vec::new();
        for highlight in &args.highlight {
            if let Some((color, words_str)) = highlight.split_once(':') {
                let words: Vec<String> = words_str
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .collect();
                custom_highlights.push((color.to_string(), words));
            }
        }

        let highlighter = Highlighter::new(enable, disable, args.disable_builtin_keywords, custom_highlights);

        if args.print || args.follow {
            for line in reader.lines() {
                let line = line?;
                println!("{}", highlighter.highlight_line(&line));
            }
        } else {
            for line in reader.lines() {
                let line = line?;
                println!("{}", highlighter.highlight_line(&line));
            }
        }
    }

    Ok(())
}
