struct SimpleRegex {
    pattern: String,
    is_word_boundary: bool,
}

impl SimpleRegex {
    fn new(pattern: &str) -> Self {
        SimpleRegex {
            pattern: pattern.to_string(),
            is_word_boundary: pattern.starts_with("\\b") || pattern.ends_with("\\b"),
        }
    }

    fn find(&self, text: &str) -> Option<(usize, usize)> {
        let pattern = if self.pattern.starts_with("\\b") {
            &self.pattern[2..]
        } else if self.pattern.ends_with("\\b") {
            &self.pattern[..self.pattern.len() - 2]
        } else {
            &self.pattern
        };

        if let Some(pos) = text.find(pattern) {
            if self.is_word_boundary {
                let before_ok = pos == 0 || !text.as_bytes()[pos - 1].is_ascii_alphanumeric();
                let after_ok = pos + pattern.len() >= text.len()
                    || !text.as_bytes()[pos + pattern.len()].is_ascii_alphanumeric();
                if before_ok && after_ok {
                    return Some((pos, pos + pattern.len()));
                }
            } else {
                return Some((pos, pos + pattern.len()));
            }
        }
        None
    }

    fn find_all(&self, text: &str) -> Vec<(usize, usize)> {
        let mut matches = Vec::new();
        let mut search_from = 0;
        while search_from < text.len() {
            if let Some((start, end)) = self.find(&text[search_from..]) {
                matches.push((search_from + start, search_from + end));
                search_from += end;
                if search_from - end == start {
                    search_from += 1;
                }
            } else {
                break;
            }
        }
        matches
    }
}

fn matches_digits_only(text: &str) -> bool {
