}

fn find_numbers(text: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i].is_ascii_digit() {
            let start = i;
            while i < chars.len() && chars[i].is_ascii_digit() {
                i += 1;
            }
            // Convert char indices to byte indices
            let byte_start = text[..text.len().min(start)].len();
            let byte_end = text[..text.len().min(i)].len();
            matches.push((byte_start, byte_end));
        } else {
            i += 1;
        }
    }
    matches
}

fn find_ipv4(text: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();
    let pattern = SimpleRegex::new("\\d+\\.\\d+\\.\\d+\\.\\d+");

    let mut search_from = 0;
    loop {
        let search_text = &text[search_from..];
        let mut found = false;

        for i in 0..search_text.len() {
            if search_text[i..].starts_with(|c: char| c.is_ascii_digit()) {
                // Try to match IP pattern
                let mut parts = Vec::new();
                let mut j = i;
                let chars: Vec<char> = search_text[i..].chars().collect();
                let mut char_idx = 0;

                loop {
                    if char_idx >= chars.len() || !chars[char_idx].is_ascii_digit() {
                        break;
                    }
                    let digit_start = char_idx;
                    while char_idx < chars.len() && chars[char_idx].is_ascii_digit() {
                        char_idx += 1;
                    }
                    parts.push((digit_start, char_idx));

                    if char_idx >= chars.len() || chars[char_idx] != '.' {
                        break;
                    }
                    char_idx += 1;
                }

                if parts.len() == 4 {
                    let start_byte = search_from + i;
                    let end_byte = search_from + i + search_text[i..].chars().take(chars.iter().take(char_idx).count()).map(|c| c.len_utf8()).sum::<usize>();
                    matches.push((start_byte, end_byte));
                    found = true;
                    search_from += i + 1;
                    break;
                }
            }
        }

        if !found {
