        Highlighter {
            enable,
            disable,
            disable_builtins,
            custom_highlights,
        }
    }

    fn should_enable(&self, name: &str) -> bool {
        if let Some(ref enabled) = self.enable {
            enabled.contains(name)
        } else if let Some(ref disabled) = self.disable {
            !disabled.contains(name)
        } else {
            true
        }
    }

    fn highlight_line(&self, line: &str) -> String {
        let mut result = line.to_string();

        // Apply builtins
        if !self.disable_builtins {
            // Log levels
            if self.should_enable("numbers") {
                result = self.replace_word_boundary(&result, "ERROR", "\x1b[31mERROR\x1b[0m");
                result = self.replace_word_boundary(&result, "WARN", "\x1b[33mWARN\x1b[0m");
                result = self.replace_word_boundary(&result, "INFO", "\x1b[37mINFO\x1b[0m");
                result = self.replace_word_boundary(&result, "DEBUG", "\x1b[32mDEBUG\x1b[0m");
                result = self.replace_word_boundary(&result, "TRACE", "\x1b[2mTRACE\x1b[0m");
            }

            // Booleans and null
            result = self.replace_word_boundary(&result, "true", "\x1b[3;31mtrue\x1b[0m");
            result = self.replace_word_boundary(&result, "false", "\x1b[3;31mfalse\x1b[0m");
            result = self.replace_word_boundary(&result, "null", "\x1b[3;31mnull\x1b[0m");

            // REST verbs - special handling
            result = self.replace_space_bounded(" GET ", "\x1b[42;30m GET \x1b[0m", &result);
            result = self.replace_space_bounded(" POST ", "\x1b[43;30m POST \x1b[0m", &result);
            result = self.replace_space_bounded(" PUT ", "\x1b[45;30m PUT \x1b[0m", &result);
            result = self.replace_space_bounded(" DELETE ", "\x1b[41;30m DELETE \x1b[0m", &result);
            result = self.replace_space_bounded(" PATCH ", "\x1b[45;30m PATCH \x1b[0m", &result);

            // SUCCESS
            result = self.replace_word_boundary(&result, "SUCCESS", "\x1b[32mSUCCESS\x1b[0m");
        }

        // Numbers
        if self.should_enable("numbers") {
            result = self.highlight_numbers(&result);
        }

        // Dates
        if self.should_enable("dates") {
            result = self.highlight_dates(&result);
        }

        // Times
        if self.should_enable("dates") {
            result = self.highlight_times(&result);
        }

        // UUIDs
        if self.should_enable("uuids") {
            result = self.highlight_uuids(&result);
        }

        // IP addresses
        if self.should_enable("ip-addresses") {
            result = self.highlight_ips(&result);
        }

        // URLs
        if self.should_enable("urls") {
            result = self.highlight_urls(&result);
        }

        // Paths
        if self.should_enable("paths") {
            result = self.highlight_paths(&result);
        }

        // Quotes
        if self.should_enable("quotes") {
            result = self.highlight_quotes(&result);
        }

        // JSON
        if self.should_enable("json") {
            result = self.highlight_json_keys(&result);
        }

        // Custom highlights
        for (color, words) in &self.custom_highlights {
            let code = match color.as_str() {
                "red" => "\x1b[31m",
                "green" => "\x1b[32m",
                "yellow" => "\x1b[33m",
                "blue" => "\x1b[34m",
                "magenta" => "\x1b[35m",
                "cyan" => "\x1b[36m",
                _ => continue,
            };

            for word in words {
                let highlighted = format!("{}{}\x1b[0m", code, word);
                result = self.replace_word_boundary(&result, word, &highlighted);
            }
        }

        result
    }

    fn replace_word_boundary(&self, text: &str, find: &str, replace: &str) -> String {
        let mut result = String::new();
        let mut last = 0;

        while let Some(pos) = text[last..].find(find) {
            let absolute_pos = last + pos;
            let before_ok = absolute_pos == 0
                || !text.as_bytes()[absolute_pos - 1].is_ascii_alphanumeric();
            let after_ok = absolute_pos + find.len() >= text.len()
                || !text.as_bytes()[absolute_pos + find.len()].is_ascii_alphanumeric();

            if before_ok && after_ok {
                result.push_str(&text[last..absolute_pos]);
                result.push_str(replace);
                last = absolute_pos + find.len();
            } else {
                result.push_str(&text[last..absolute_pos + 1]);
                last = absolute_pos + 1;
            }
        }

        result.push_str(&text[last..]);
        result
    }

    fn replace_space_bounded(&self, find: &str, replace: &str, text: &str) -> String {
        text.replace(find, replace)
    }

    fn highlight_numbers(&self, text: &str) -> String {
        let mut result = String::new();
        let mut last = 0;
        let mut i = 0;
        let chars: Vec<char> = text.chars().collect();

        while i < chars.len() {
            if chars[i].is_ascii_digit() {
                let mut j = i;
                while j < chars.len() && chars[j].is_ascii_digit() {
                    j += 1;
                }

                // Check word boundaries
                let before_ok = i == 0 || !chars[i - 1].is_ascii_alphanumeric();
                let after_ok = j >= chars.len() || !chars[j].is_ascii_alphanumeric();

                if before_ok && after_ok {
                    // Convert char index to byte position
                    let byte_start: usize = chars[..i].iter().map(|c| c.len_utf8()).sum();
                    let byte_end: usize = chars[..j].iter().map(|c| c.len_utf8()).sum();

                    result.push_str(&text[last..byte_start]);
                    result.push_str("\x1b[36m");
                    result.push_str(&text[byte_start..byte_end]);
                    result.push_str("\x1b[0m");
                    last = byte_end;
                    i = j;
                } else {
                    i = j;
                }
            } else {
                i += 1;
            }
        }

        result.push_str(&text[last..]);
        result
    }

    fn highlight_dates(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            // Look for date pattern: YYYY-MM-DD or YYYY/MM/DD
            if pos + 10 <= text.len() {
                let slice = &text[pos..pos + 10];
                if is_date_pattern(slice) {
                    result.push_str(&text[..pos]);
                    // Check word boundary
                    let before_ok = pos == 0
                        || !text.as_bytes()[pos - 1].is_ascii_alphanumeric();
                    let after_char = if pos + 10 < text.len() {
                        text.as_bytes()[pos + 10] as char
                    } else {
                        ' '
                    };
                    let after_ok = pos + 10 >= text.len() || !after_char.is_ascii_alphanumeric();

                    if before_ok && after_ok {
                        result.push_str(&self.highlight_date_string(slice));
                        return result + &self.highlight_dates(&text[pos + 10..]);
                    }
                }
            }
            pos += 1;
        }

        text.to_string()
    }

    fn highlight_date_string(&self, date: &str) -> String {
        let mut result = String::new();
        for (i, part) in date.split(|c| c == '-' || c == '/').enumerate() {
            if i > 0 {
                if date.contains('-') {
                    result.push_str("\x1b[2m-\x1b[0m");
                } else {
                    result.push_str("\x1b[2m/\x1b[0m");
                }
            }
            result.push_str("\x1b[35m");
            result.push_str(part);
            result.push_str("\x1b[0m");
        }
        result
    }

    fn highlight_times(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            // Look for time pattern HH:MM:SS or HH:MM
            let remaining = &text[pos..];

            // Try HH:MM:SS format
            if remaining.len() >= 8 {
                let slice = &remaining[..8];
                if is_time_pattern_hms(slice) {
                    let before_ok = pos == 0 || !text.as_bytes()[pos - 1].is_ascii_alphanumeric();
                    let after_ok = pos + 8 >= text.len() || !text.as_bytes()[pos + 8].is_ascii_alphanumeric();

                    if before_ok && after_ok {
                        result.push_str(&text[..pos]);
                        result.push_str("\x1b[34m");
                        result.push_str(&slice[..2]);
                        result.push_str("\x1b[0m\x1b[2m:\x1b[0m\x1b[34m");
                        result.push_str(&slice[3..5]);
                        result.push_str("\x1b[0m\x1b[2m:\x1b[0m\x1b[34m");
                        result.push_str(&slice[6..8]);
                        result.push_str("\x1b[0m");
                        return result + &self.highlight_times(&text[pos + 8..]);
                    }
                }
            }

            // Try HH:MM format
            if remaining.len() >= 5 {
                let slice = &remaining[..5];
                if is_time_pattern_hm(slice) {
                    let before_ok = pos == 0 || !text.as_bytes()[pos - 1].is_ascii_alphanumeric();
                    let after_ok = pos + 5 >= text.len() || !text.as_bytes()[pos + 5].is_ascii_alphanumeric();

                    if before_ok && after_ok {
                        result.push_str(&text[..pos]);
                        result.push_str("\x1b[36m");
                        result.push_str(&slice[..2]);
                        result.push_str("\x1b[0m:\x1b[36m");
                        result.push_str(&slice[3..5]);
                        result.push_str("\x1b[0m");
                        return result + &self.highlight_times(&text[pos + 5..]);
                    }
                }
            }

            pos += 1;
        }

        text.to_string()
    }

    fn highlight_uuids(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            if pos + 36 <= text.len() {
                let slice = &text[pos..pos + 36];
                if is_uuid_pattern(slice) {
                    let before_ok = pos == 0 || !text.as_bytes()[pos - 1].is_ascii_alphanumeric();
                    let after_ok = pos + 36 >= text.len() || !text.as_bytes()[pos + 36].is_ascii_alphanumeric();

                    if before_ok && after_ok {
                        result.push_str(&text[..pos]);
                        result.push_str(&self.highlight_uuid(slice));
                        return result + &self.highlight_uuids(&text[pos + 36..]);
                    }
                }
            }
            pos += 1;
        }

        text.to_string()
    }

    fn highlight_uuid(&self, uuid: &str) -> String {
        let mut result = String::new();
        for c in uuid.chars() {
            if c == '-' {
                result.push_str("\x1b[31m-\x1b[0m");
            } else if c.is_ascii_hexdigit() {
                if c.is_ascii_lowercase() || (c.is_ascii_uppercase() && c < 'F') {
                    result.push_str("\x1b[3;35m");
                } else {
                    result.push_str("\x1b[3;34m");
                }
                result.push(c);
                result.push_str("\x1b[0m");
            }
        }
        result
    }

    fn highlight_ips(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            // Try IPv4
            if let Some((start, end, ip_text)) = find_ipv4_at(text, pos) {
                result.push_str(&text[..start]);
                result.push_str(&self.highlight_ipv4(&ip_text));
                return result + &self.highlight_ips(&text[end..]);
            }

            // Try IPv6
            if let Some((start, end, ip_text)) = find_ipv6_at(text, pos) {
                result.push_str(&text[..start]);
                result.push_str(&self.highlight_ipv6(&ip_text));
                return result + &self.highlight_ips(&text[end..]);
            }

            pos += 1;
        }

        text.to_string()
    }

    fn highlight_ipv4(&self, ip: &str) -> String {
        let mut result = String::new();
        for (i, part) in ip.split('.').enumerate() {
            if i > 0 {
                result.push_str("\x1b[31m.\x1b[0m");
            }
            result.push_str("\x1b[3;34m");
            result.push_str(part);
            result.push_str("\x1b[0m");
        }
        result
    }

    fn highlight_ipv6(&self, ip: &str) -> String {
        let mut result = String::new();
        for (i, part) in ip.split(':').enumerate() {
            if i > 0 {
                result.push_str("\x1b[31m:\x1b[0m");
            }
            for c in part.chars() {
                if c.is_ascii_hexdigit() {
                    if c.is_ascii_lowercase() || (c.is_ascii_uppercase() && c < 'F') {
                        result.push_str("\x1b[3;35m");
                    } else {
                        result.push_str("\x1b[3;34m");
                    }
                    result.push(c);
                    result.push_str("\x1b[0m");
                } else {
                    result.push(c);
                }
            }
        }
        result
    }

    fn highlight_urls(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            if let Some((start, end)) = find_http_url_at(text, pos) {
                result.push_str(&text[..start]);
                let url = &text[start..end];
                result.push_str(&self.highlight_url(url));
                return result + &self.highlight_urls(&text[end..]);
            }
            pos += 1;
        }

        text.to_string()
    }

    fn highlight_url(&self, url: &str) -> String {
        if let Some(pos) = url.find("://") {
            let scheme = &url[..pos];
            let rest = &url[pos + 3..];

            let scheme_colored = if scheme == "http" {
                "\x1b[2;31mhttp\x1b[0m"
            } else if scheme == "https" {
                "\x1b[2;32mhttps\x1b[0m"
            } else {
                scheme
            };

            if let Some(slash_pos) = rest.find('/') {
                let domain = &rest[..slash_pos];
                let path = &rest[slash_pos..];
                format!(
                    "{}{}\x1b[2;34m{}\x1b[0m\x1b[34m{}\x1b[0m",
                    scheme_colored, "://", domain, path
                )
            } else {
                format!(
                    "{}{}\x1b[2;34m{}\x1b[0m",
                    scheme_colored, "://", rest
                )
            }
        } else {
            url.to_string()
        }
    }

    fn highlight_paths(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            if let Some((start, end)) = find_path_at(text, pos) {
                result.push_str(&text[..start]);
                let path = &text[start..end];
                result.push_str(&self.highlight_path(path));
                return result + &self.highlight_paths(&text[end..]);
            }
            pos += 1;
        }

        text.to_string()
    }

    fn highlight_path(&self, path: &str) -> String {
        let mut result = String::new();
        for (i, part) in path.split('/').enumerate() {
            if i > 0 {
                result.push_str("\x1b[33m/\x1b[0m");
            }
            if !part.is_empty() {
                result.push_str("\x1b[32m");
                result.push_str(part);
                result.push_str("\x1b[0m");
            }
        }
        result
    }

    fn highlight_quotes(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            if text.as_bytes()[pos] == b'"' {
                let end = text[pos + 1..].find('"').map(|p| p + pos + 1);
                if let Some(end_pos) = end {
                    result.push_str(&text[..pos]);
                    result.push_str("\x1b[33m");
                    result.push_str(&text[pos..end_pos + 1]);
                    result.push_str("\x1b[0m");
                    return result + &self.highlight_quotes(&text[end_pos + 1..]);
                }
            }
            pos += 1;
        }

        text.to_string()
    }

    fn highlight_json_keys(&self, text: &str) -> String {
        let mut result = String::new();
        let mut pos = 0;

        while pos < text.len() {
            if text.as_bytes()[pos] == b'"' {
                let end = text[pos + 1..].find('"').map(|p| p + pos + 1);
                if let Some(end_pos) = end {
                    // Check if followed by a colon (possibly with spaces)
                    let after = &text[end_pos + 1..];
                    if after.trim_start().starts_with(':') {
                        result.push_str(&text[..pos]);
                        result.push_str("\x1b[33m");
                        result.push_str(&text[pos..end_pos + 1]);
                        result.push_str("\x1b[0m");
                        return result + &self.highlight_json_keys(&text[end_pos + 1..]);
                    }
                }
            }
            pos += 1;
        }

        text.to_string()
    }
}

fn is_date_pattern(s: &str) -> bool {
    if s.len() < 10 {
        return false;
    }
    let parts: Vec<&str> = if s.contains('-') {
        s.split('-').collect()
    } else if s.contains('/') {
        s.split('/').collect()
    } else {
        return false;
    };

    if parts.len() != 3 {
        return false;
    }

    let year = parts[0].parse::<u32>().ok();
    let month = parts[1].parse::<u32>().ok();
    let day = parts[2].parse::<u32>().ok();

    year.is_some() && month.is_some() && day.is_some()
}

fn is_time_pattern_hms(s: &str) -> bool {
    s.len() >= 8
        && s[..2].chars().all(|c| c.is_ascii_digit())
        && s.as_bytes()[2] == b':'
        && s[3..5].chars().all(|c| c.is_ascii_digit())
        && s.as_bytes()[5] == b':'
        && s[6..8].chars().all(|c| c.is_ascii_digit())
}

fn is_time_pattern_hm(s: &str) -> bool {
    s.len() >= 5
        && s[..2].chars().all(|c| c.is_ascii_digit())
        && s.as_bytes()[2] == b':'
        && s[3..5].chars().all(|c| c.is_ascii_digit())
}

fn is_uuid_pattern(s: &str) -> bool {
    if s.len() != 36 {
        return false;
    }
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() != 5 {
        return false;
    }
    if parts[0].len() != 8
        || parts[1].len() != 4
        || parts[2].len() != 4
        || parts[3].len() != 4
        || parts[4].len() != 12
    {
        return false;
    }
    parts
        .iter()
        .all(|p| p.chars().all(|c| c.is_ascii_hexdigit()))
}

fn find_ipv4_at(text: &str, start: usize) -> Option<(usize, usize, String)> {
    for pos in start..text.len().saturating_sub(7) {
        let remaining = &text[pos..];
        let mut num_count = 0;
        let mut current_pos = 0;
        let mut parts = Vec::new();

        for _ in 0..4 {
            while current_pos < remaining.len()
                && remaining.as_bytes()[current_pos] == b' '
            {
                current_pos += 1;
            }

            if current_pos >= remaining.len() || !remaining.as_bytes()[current_pos].is_ascii_digit() {
                break;
            }

            let start_num = current_pos;
            while current_pos < remaining.len() && remaining.as_bytes()[current_pos].is_ascii_digit() {
                current_pos += 1;
            }
            parts.push(&remaining[start_num..current_pos]);
            num_count += 1;

            if current_pos >= remaining.len() || remaining.as_bytes()[current_pos] != b'.' {
                if num_count < 4 {
                    break;
                }
            } else {
                current_pos += 1;
            }
        }

        if parts.len() == 4
            && (pos == 0 || !text.as_bytes()[pos - 1].is_ascii_alphanumeric())
            && (pos + current_pos >= text.len()
                || !text.as_bytes()[pos + current_pos].is_ascii_alphanumeric())
        {
            let ip_str = parts.join(".");
            return Some((pos, pos + current_pos, ip_str));
        }
    }
    None
}

fn find_ipv6_at(text: &str, start: usize) -> Option<(usize, usize, String)> {
    None
}

fn find_http_url_at(text: &str, start: usize) -> Option<(usize, usize)> {
    if let Some(pos) = text[start..].find("http") {
        let abs_pos = start + pos;
        if abs_pos + 4 < text.len() {
            let scheme_start = abs_pos;
            let remaining = &text[abs_pos..];

            // Check if it's http:// or https://
            if remaining.starts_with("https://") {
                let url_end = remaining[8..]
                    .find(|c: char| c.is_whitespace() || c == '\'' || c == '"')
                    .map(|p| abs_pos + 8 + p)
                    .unwrap_or(text.len());
                return Some((scheme_start, url_end));
            } else if remaining.starts_with("http://") {
                let url_end = remaining[7..]
                    .find(|c: char| c.is_whitespace() || c == '\'' || c == '"')
                    .map(|p| abs_pos + 7 + p)
                    .unwrap_or(text.len());
                return Some((scheme_start, url_end));
            }
        }
    }
    None
}

fn find_path_at(text: &str, start: usize) -> Option<(usize, usize)> {
    if start >= text.len() {
        return None;
    }

    if text.as_bytes()[start] == b'/' {
        let mut end = start + 1;
        while end < text.len() && text.as_bytes()[end] != b' ' && text.as_bytes()[end] != b'\n' {
            end += 1;
        }
        return Some((start, end));
    }

    None
}

fn main() {
    let args = parse_args();

    let enable = args.enable.clone();
    let disable = args.disable.clone();
    let disable_builtins = args.disable_builtin_keywords;
    let custom_highlights = args.highlight.clone();

    let highlighter = Highlighter::new(enable, disable, disable_builtins, custom_highlights);

    if args.file.is_none() {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();

        for line in reader.lines() {
            if let Ok(line) = line {
                println!("{}", highlighter.highlight_line(&line));
            }
        }
    } else if let Some(file_path) = args.file {
        match fs::File::open(&file_path) {
            Ok(file) => {
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    if let Ok(line) = line {
                        println!("{}", highlighter.highlight_line(&line));
                    }
                }
            }
            Err(e) => {
                eprintln!("Error opening file: {}", e);
                std::process::exit(1);
            }
        }
    }
}
