        enable: Option<HashSet<String>>,
        disable: Option<HashSet<String>>,
        disable_builtins: bool,
        custom_highlights: Vec<(String, Vec<String>)>,
    ) -> Self {
        Highlighter {
            enable,
            disable,
            disable_builtins,
            custom_highlights,
        }
    }

    fn should_enable(&self, name: &str) -> bool {
        if let Some(ref enabled) = self.enable {
            enabled.contains(name)
        } else if let Some(ref disabled) = self.disable {
            !disabled.contains(name)
        } else {
            true
        }
    }

    fn highlight_line(&self, line: &str) -> String {
        self.apply_all_highlighters(line)
    }

    fn apply_all_highlighters(&self, text: &str) -> String {
        let mut result = String::new();
        let mut i = 0;

        while i < text.len() {
            // Try to match complex patterns first (dates, times, etc.)
            if let Some((end, highlighted)) = self.try_match_complex(text, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            // Try to match simple keywords
            if let Some((end, highlighted)) = self.try_match_keyword(text, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            // No match, just add the character
            if let Some(ch) = text[i..].chars().next() {
                result.push(ch);
                i += ch.len_utf8();
            } else {
                i += 1;
            }
        }

        result
    }

    fn try_match_complex(&self, text: &str, pos: usize) -> Option<(usize, String)> {
        let remaining = &text[pos..];

        // Try UUID (36 bytes)
        if self.should_enable("uuids") && remaining.len() >= 36 {
            if let Some(uuid) = self.try_uuid(&remaining[..36]) {
