struct Highlighter {
    enable: Option<HashSet<String>>,
    disable: Option<HashSet<String>>,
    disable_builtins: bool,
    custom_highlights: Vec<(String, Vec<String>)>,
}

impl Highlighter {
    fn new(
        enable: Option<HashSet<String>>,
        disable: Option<HashSet<String>>,
        disable_builtins: bool,
        custom_highlights: Vec<(String, Vec<String>)>,
    ) -> Self {
        Highlighter {
            enable,
            disable,
            disable_builtins,
            custom_highlights,
        }
    }

    fn should_enable(&self, name: &str) -> bool {
        if let Some(ref enabled) = self.enable {
            enabled.contains(name)
        } else if let Some(ref disabled) = self.disable {
            !disabled.contains(name)
        } else {
            true
        }
    }

    fn highlight_line(&self, line: &str) -> String {
        self.apply_all_highlighters(line)
    }

    fn apply_all_highlighters(&self, text: &str) -> String {
        let mut result = String::new();
        let mut i = 0;

        while i < text.len() {
            // Try to match complex patterns first (dates, times, etc.)
            if let Some((end, highlighted)) = self.try_match_complex(text, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            // Try to match simple keywords
            if let Some((end, highlighted)) = self.try_match_keyword(text, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            // No match, just add the character
            if let Some(ch) = text[i..].chars().next() {
                result.push(ch);
                i += ch.len_utf8();
            } else {
                i += 1;
            }
        }

        result
    }

    fn try_match_complex(&self, text: &str, pos: usize) -> Option<(usize, String)> {
        let remaining = &text[pos..];

        // Try UUID (36 bytes)
        if self.should_enable("uuids") && remaining.len() >= 36 {
            if let Some(uuid) = self.try_uuid(&remaining[..36]) {
                return Some((pos + 36, self.highlight_uuid(uuid)));
            }
        }

        // Try IPv4 address
        if self.should_enable("ip-addresses") {
            if let Some((len, addr)) = self.try_ipv4(remaining) {
                return Some((pos + len, self.highlight_ipv4(&addr)));
            }
        }

        // Try IPv6 address
        if self.should_enable("ip-addresses") {
            if let Some((len, addr)) = self.try_ipv6(remaining) {
                return Some((pos + len, self.highlight_ipv6(&addr)));
            }
        }

        // Try date pattern (YYYY-MM-DD or YYYY/MM/DD)
        if self.should_enable("dates") && remaining.len() >= 10 {
            if is_date_pattern(&remaining[..10]) {
                return Some((pos + 10, self.highlight_date(&remaining[..10])));
            }
        }

        // Try time pattern (HH:MM:SS.fff or HH:MM:SS or HH:MM)
        if self.should_enable("dates") {
            if let Some((len, time_str)) = self.try_time(remaining) {
                return Some((pos + len, self.highlight_time(time_str)));
            }
        }

        // Try URL
        if self.should_enable("urls") {
            if let Some((len, url)) = self.try_url(remaining) {
                return Some((pos + len, self.highlight_url(&url)));
            }
        }

        // Try path
        if self.should_enable("paths") {
            if let Some((len, path)) = self.try_path(remaining) {
                return Some((pos + len, self.highlight_path(&path)));
            }
        }

        // Try double-quoted string
        if self.should_enable("quotes") && remaining.starts_with('"') {
            if let Some(end) = remaining[1..].find('"') {
                let quoted = &remaining[..end + 2];
                return Some((pos + end + 2, format!("\x1b[33m{}\x1b[0m", quoted)));
            }
        }

        None
    }

    fn try_match_keyword(&self, text: &str, pos: usize) -> Option<(usize, String)> {
        let remaining = &text[pos..];
        let chars: Vec<char> = remaining.chars().collect();

        // Check if start is word boundary
        let is_start_boundary = pos == 0 || !text.as_bytes()[pos - 1].is_ascii_alphanumeric();

        if !is_start_boundary {
            return None;
        }

        // Log levels
        if !self.disable_builtins && self.should_enable("numbers") {
            if remaining.starts_with("ERROR") && (remaining.len() == 5 || !chars.get(5).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 5, "\x1b[31mERROR\x1b[0m".to_string()));
            }
            if remaining.starts_with("WARN") && (remaining.len() == 4 || !chars.get(4).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 4, "\x1b[33mWARN\x1b[0m".to_string()));
            }
            if remaining.starts_with("INFO") && (remaining.len() == 4 || !chars.get(4).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 4, "\x1b[37mINFO\x1b[0m".to_string()));
            }
            if remaining.starts_with("DEBUG") && (remaining.len() == 5 || !chars.get(5).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 5, "\x1b[32mDEBUG\x1b[0m".to_string()));
            }
            if remaining.starts_with("TRACE") && (remaining.len() == 5 || !chars.get(5).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 5, "\x1b[2mTRACE\x1b[0m".to_string()));
            }
        }

        // Boolean values
        if !self.disable_builtins {
            if remaining.starts_with("true") && (remaining.len() == 4 || !chars.get(4).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 4, "\x1b[3;31mtrue\x1b[0m".to_string()));
            }
            if remaining.starts_with("false") && (remaining.len() == 5 || !chars.get(5).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 5, "\x1b[3;31mfalse\x1b[0m".to_string()));
            }
            if remaining.starts_with("null") && (remaining.len() == 4 || !chars.get(4).map_or(false, |c| c.is_ascii_alphanumeric())) {
                return Some((pos + 4, "\x1b[3;31mnull\x1b[0m".to_string()));
            }
        }

        // REST verbs with space
        if !self.disable_builtins {
            if remaining.starts_with(" GET ") {
                return Some((pos + 5, "\x1b[42;30m GET \x1b[0m".to_string()));
            }
            if remaining.starts_with(" POST ") {
                return Some((pos + 6, "\x1b[43;30m POST \x1b[0m".to_string()));
            }
            if remaining.starts_with(" PUT ") {
                return Some((pos + 5, "\x1b[45;30m PUT \x1b[0m".to_string()));
            }
            if remaining.starts_with(" DELETE ") {
                return Some((pos + 8, "\x1b[41;30m DELETE \x1b[0m".to_string()));
            }
            if remaining.starts_with(" PATCH ") {
                return Some((pos + 7, "\x1b[45;30m PATCH \x1b[0m".to_string()));
            }
        }

        // SUCCESS keyword
        if !self.disable_builtins && remaining.starts_with("SUCCESS") && (remaining.len() == 7 || !chars.get(7).map_or(false, |c| c.is_ascii_alphanumeric())) {
            return Some((pos + 7, "\x1b[32mSUCCESS\x1b[0m".to_string()));
        }

        // Process names (for patterns like "processname[" or "(processname)")
        if self.should_enable("processes") {
            if let Some((end, name)) = self.try_process_name(remaining) {
                return Some((pos + end, format!("\x1b[33m{}\x1b[0m", name)));
            }
        }

        // Numbers
        if self.should_enable("numbers") {
            if remaining.chars().next().map_or(false, |c| c.is_ascii_digit()) {
                let mut end = 0;
                for c in remaining.chars() {
                    if c.is_ascii_digit() {
                        end += c.len_utf8();
                    } else {
                        break;
                    }
                }
                if end > 0 && (end >= remaining.len() || !remaining.as_bytes()[end].is_ascii_alphanumeric()) {
                    let num = &remaining[..end];
                    return Some((pos + end, format!("\x1b[36m{}\x1b[0m", num)));
                }
            }
        }

        // Custom highlights
        for (color, words) in &self.custom_highlights {
            let code = match color.as_str() {
                "red" => "\x1b[31m",
                "green" => "\x1b[32m",
                "yellow" => "\x1b[33m",
                "blue" => "\x1b[34m",
                "magenta" => "\x1b[35m",
                "cyan" => "\x1b[36m",
                _ => continue,
            };

            for word in words {
                if remaining.starts_with(word) {
                    let next_char_ok = word.len() >= remaining.len() || !remaining.as_bytes()[word.len()].is_ascii_alphanumeric();
                    if next_char_ok {
                        return Some((pos + word.len(), format!("{}{}\x1b[0m", code, word)));
                    }
                }
            }
        }

        None
    }

    fn try_process_name(&self, text: &str) -> Option<(usize, String)> {
        let mut i = 0;
        let chars: Vec<char> = text.chars().collect();

        // Match word characters and hyphens
        while i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '_' || chars[i] == '-') {
            i += 1;
        }

        // Check if followed by [ or (
        if i > 0 && i < chars.len() && (chars[i] == '[' || chars[i] == '(') {
            let name_bytes: String = chars[..i].iter().collect();
            return Some((i, name_bytes));
        }

        None
    }

    fn try_uuid(&self, text: &str) -> Option<String> {
        if text.len() < 36 {
            return None;
        }
        let candidate = &text[..36];
        if is_uuid_pattern(candidate) {
            Some(candidate.to_string())
        } else {
            None
        }
    }

    fn try_ipv4(&self, text: &str) -> Option<(usize, String)> {
        let chars: Vec<char> = text.chars().collect();
        let mut parts = 0;
        let mut digit_count = 0;

        for (idx, &ch) in chars.iter().enumerate() {
            if ch.is_ascii_digit() {
                digit_count += 1;
            } else if ch == '.' {
                if digit_count > 0 {
                    parts += 1;
                    digit_count = 0;
                } else {
                    return None;
                }
            } else if digit_count > 0 {
                // Found non-digit non-dot after digits
                if parts == 3 {
                    let candidate = &text[..idx];
                    if is_ipv4_pattern(candidate) {
                        return Some((idx, candidate.to_string()));
                    }
                }
                return None;
            } else {
                return None;
            }
        }

        if digit_count > 0 && parts == 3 {
            let candidate = text;
            if is_ipv4_pattern(candidate) {
                return Some((candidate.len(), candidate.to_string()));
            }
        }

        None
    }

    fn try_ipv6(&self, _text: &str) -> Option<(usize, String)> {
        None
    }

    fn try_time(&self, text: &str) -> Option<(usize, String)> {
        // Try HH:MM:SS.ffffff format
        if text.len() >= 8 && is_time_pattern_hms(text) {
            let mut end = 8;
            // Check for fractional seconds
            if text.len() > 8 && text.as_bytes()[8] == b'.' {
                end = 9;
                while end < text.len() && text.as_bytes()[end].is_ascii_digit() && end - 9 < 9 {
                    end += 1;
                }
            }
            return Some((end, text[..end].to_string()));
        }

        // Try HH:MM format
        if text.len() >= 5 && is_time_pattern_hm(text) {
            return Some((5, text[..5].to_string()));
        }

        None
    }

    fn try_url(&self, text: &str) -> Option<(usize, String)> {
        if let Some(pos) = text.find("://") {
            let scheme = &text[..pos];
            if scheme == "http" || scheme == "https" || scheme == "ftp" {
                let start = pos + 3;
                let mut end = start;
                while end < text.len() {
                    let ch = text.as_bytes()[end];
                    if ch == b' ' || ch == b'\n' || ch == b'\r' || ch == b'"' || ch == b'\'' {
                        break;
                    }
                    end += 1;
                }
                return Some((end, text[..end].to_string()));
            }
        }
        None
    }

    fn try_path(&self, text: &str) -> Option<(usize, String)> {
        if text.starts_with('/') {
            let mut end = 1;
            while end < text.len() {
                let ch = text.as_bytes()[end];
                if (ch as char).is_whitespace() {
                    break;
                }
                end += 1;
            }
            if end > 1 {
                return Some((end, text[..end].to_string()));
            }
        }
        None
    }

    fn highlight_uuid(&self, uuid: &str) -> String {
        let mut result = String::new();
        for c in uuid.chars() {
            if c == '-' {
                result.push_str("\x1b[31m-\x1b[0m");
            } else if c.is_ascii_hexdigit() {
                if c.is_ascii_lowercase() || (c.is_ascii_uppercase() && c < 'F') {
                    result.push_str("\x1b[3;35m");
                } else {
                    result.push_str("\x1b[3;34m");
                }
                result.push(c);
                result.push_str("\x1b[0m");
            }
        }
        result
    }

    fn highlight_ipv4(&self, ip: &str) -> String {
        let mut result = String::new();
        for (i, part) in ip.split('.').enumerate() {
            if i > 0 {
                result.push_str("\x1b[31m.\x1b[0m");
            }
            result.push_str("\x1b[3;34m");
            result.push_str(part);
            result.push_str("\x1b[0m");
        }
        result
    }

    fn highlight_ipv6(&self, ip: &str) -> String {
        let mut result = String::new();
        for (i, part) in ip.split(':').enumerate() {
            if i > 0 {
                result.push_str("\x1b[31m:\x1b[0m");
            }
            for c in part.chars() {
                if c.is_ascii_hexdigit() {
                    if c.is_ascii_lowercase() || (c.is_ascii_uppercase() && c < 'F') {
                        result.push_str("\x1b[3;35m");
                    } else {
                        result.push_str("\x1b[3;34m");
                    }
                    result.push(c);
                    result.push_str("\x1b[0m");
                } else {
                    result.push(c);
                }
            }
        }
        result
    }

    fn highlight_date(&self, date: &str) -> String {
        let mut result = String::new();
        let sep = if date.contains('-') { '-' } else { '/' };
        for (i, part) in date.split(sep).enumerate() {
            if i > 0 {
                result.push_str(&format!("\x1b[2m{}\x1b[0m", sep));
            }
            result.push_str("\x1b[35m");
            result.push_str(part);
            result.push_str("\x1b[0m");
        }
        result
    }

    fn highlight_time(&self, time: &str) -> String {
        let mut result = String::new();
        let parts: Vec<&str> = if time.contains(':') {
            time.split(':').collect()
        } else {
            return time.to_string();
        };

        for (i, part) in parts.iter().enumerate() {
            if i > 0 {
                result.push_str("\x1b[2m:\x1b[0m");
            }

            // Check if this part has fractional seconds (contains .)
            if part.contains('.') {
                let subparts: Vec<&str> = part.split('.').collect();
                result.push_str("\x1b[34m");
                result.push_str(subparts[0]);
                result.push_str("\x1b[0m\x1b[2m.\x1b[0m");
                if subparts.len() > 1 {
                    result.push_str("\x1b[34m");
                    result.push_str(subparts[1]);
                    result.push_str("\x1b[0m");
                }
            } else {
                result.push_str("\x1b[34m");
                result.push_str(part);
                result.push_str("\x1b[0m");
            }
        }
        result
    }

    fn highlight_url(&self, url: &str) -> String {
        if let Some(pos) = url.find("://") {
            let scheme = &url[..pos];
            let rest = &url[pos + 3..];

            let scheme_colored = match scheme {
                "http" => "\x1b[2;31mhttp\x1b[0m",
                "https" => "\x1b[2;32mhttps\x1b[0m",
                "ftp" => "\x1b[2;31mftp\x1b[0m",
                _ => scheme,
            };

            let protocol_sep = "://";
            if let Some(slash_pos) = rest.find('/') {
                let domain = &rest[..slash_pos];
                let path = &rest[slash_pos..];
                format!(
                    "{}{}\x1b[2;34m{}\x1b[0m\x1b[34m{}\x1b[0m",
                    scheme_colored, protocol_sep, domain, path
                )
            } else {
                format!(
                    "{}{}\x1b[2;34m{}\x1b[0m",
                    scheme_colored, protocol_sep, rest
                )
            }
        } else {
            url.to_string()
        }
    }

    fn highlight_path(&self, path: &str) -> String {
        let mut result = String::new();
        for (i, part) in path.split('/').enumerate() {
            if i > 0 {
                result.push_str("\x1b[33m/\x1b[0m");
            }
            if !part.is_empty() {
                result.push_str("\x1b[32m");
                result.push_str(part);
                result.push_str("\x1b[0m");
            }
        }
        result
    }
}

fn is_date_pattern(s: &str) -> bool {
    if s.len() < 10 {
        return false;
    }
    let separator = if s.contains('-') { '-' } else if s.contains('/') { '/' } else { return false; };
    let parts: Vec<&str> = s.split(separator).collect();

    if parts.len() != 3 {
        return false;
    }

    // Check all parts are digits
    parts.iter().all(|p| !p.is_empty() && p.len() <= 4 && p.chars().all(|c| c.is_ascii_digit()))
}

fn is_time_pattern_hms(s: &str) -> bool {
    s.len() >= 8
        && s[..2].chars().all(|c| c.is_ascii_digit())
        && s.as_bytes()[2] == b':'
        && s[3..5].chars().all(|c| c.is_ascii_digit())
        && s.as_bytes()[5] == b':'
        && s[6..8].chars().all(|c| c.is_ascii_digit())
}

fn is_time_pattern_hm(s: &str) -> bool {
    s.len() >= 5
        && s[..2].chars().all(|c| c.is_ascii_digit())
        && s.as_bytes()[2] == b':'
        && s[3..5].chars().all(|c| c.is_ascii_digit())
}

fn is_uuid_pattern(s: &str) -> bool {
    if s.len() != 36 {
        return false;
    }
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() != 5 {
        return false;
    }
    if parts[0].len() != 8 || parts[1].len() != 4 || parts[2].len() != 4 || parts[3].len() != 4 || parts[4].len() != 12 {
        return false;
    }
    parts.iter().all(|p| p.chars().all(|c| c.is_ascii_hexdigit()))
}

fn is_ipv4_pattern(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }
    parts.iter().all(|p| {
        if p.is_empty() {
            return false;
        }
        if !p.chars().all(|c| c.is_ascii_digit()) {
            return false;
        }
        if let Ok(num) = p.parse::<u32>() {
            num <= 255
        } else {
            false
        }
    })
}

fn main() {
    let args = parse_args();

    let enable = args.enable.clone();
    let disable = args.disable.clone();
    let disable_builtins = args.disable_builtin_keywords;
    let custom_highlights = args.highlight.clone();

    let highlighter = Highlighter::new(enable, disable, disable_builtins, custom_highlights);

    if args.file.is_none() {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();

        for line in reader.lines() {
            if let Ok(line) = line {
                println!("{}", highlighter.highlight_line(&line));
            }
        }
    } else if let Some(file_path) = args.file {
        match fs::File::open(&file_path) {
            Ok(file) => {
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    if let Ok(line) = line {
                        println!("{}", highlighter.highlight_line(&line));
                    }
                }
            }
            Err(e) => {
                eprintln!("Error opening file: {}", e);
                std::process::exit(1);
            }
        }
    }
}
