}

fn parse_args() -> Args {
    let mut args = env::args().skip(1).peekable();
    let mut file = None;
    let mut print_flag = false;
    let mut highlight = Vec::new();
    let mut enable = None;
    let mut disable = None;
    let mut disable_builtin_keywords = false;

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--help" | "-h" => {
                println!("A log file highlighter\n");
                println!("Usage: executable [OPTIONS] [FILE]\n");
                println!("Arguments:");
                println!("  [FILE]");
                println!("          Filepath\n");
                println!("Options:");
                println!("  -f, --follow");
                println!("          Follow the contents of a file\n");
                println!("  -p, --print");
                println!("          Print the output to stdout\n");
                println!("      --config-path <CONFIG_PATH>");
                println!("          Provide a custom path to a configuration file\n");
                println!("  -e, --exec <EXEC>");
                println!("          Run command and view the output in a pager\n");
                println!("      --highlight <COLOR_WORD>");
                println!("          Highlights in the form color:word1,word2\n");
                println!("      --enable <ENABLED_HIGHLIGHTERS>");
                println!("          Enable specific highlighters\n");
                println!("      --disable <DISABLED_HIGHLIGHTERS>");
                println!("          Disable specific highlighters\n");
                println!("      --disable-builtin-keywords");
                println!("          Disable the highlighting of all builtin keyword groups\n");
                println!("      --pager <PAGER>");
                println!("          Override the default pager command used by tspin\n");
                println!("  -h, --help");
                println!("          Print help\n");
                println!("  -V, --version");
                println!("          Print version");
                std::process::exit(0);
            }
            "--version" | "-V" => {
                println!("tspin 5.6.0");
                std::process::exit(0);
            }
            "-f" | "--follow" => {},
            "-p" | "--print" => print_flag = true,
            "--config-path" => { args.next(); },
            "-e" | "--exec" => { args.next(); },
            "--highlight" => {
                if let Some(h) = args.next() {
                    if let Some((color, words_str)) = h.split_once(':') {
                        let words: Vec<String> = words_str
                            .split(',')
                            .map(|s| s.trim().to_string())
                            .collect();
                        highlight.push((color.to_string(), words));
                    }
                }
            }
            "--enable" => {
                if let Some(e) = args.next() {
                    let set: HashSet<String> = e
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .collect();
                    enable = Some(set);
                }
            }
            "--disable" => {
                if let Some(d) = args.next() {
                    let set: HashSet<String> = d
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .collect();
                    disable = Some(set);
                }
            }
            "--disable-builtin-keywords" => disable_builtin_keywords = true,
            "--pager" => { args.next(); },
            s if !s.starts_with('-') => {
                file = Some(PathBuf::from(s));
            }
            _ => {}
        }
    }

    Args {
        file,
        print_flag,
        highlight,
        enable,
        disable,
        disable_builtin_keywords,
    }
}

struct Highlighter {
    enable: Option<HashSet<String>>,
    disable: Option<HashSet<String>>,
    disable_builtins: bool,
    custom_highlights: Vec<(String, Vec<String>)>,
}

impl Highlighter {
    fn new(
        enable: Option<HashSet<String>>,
        disable: Option<HashSet<String>>,
        disable_builtins: bool,
        custom_highlights: Vec<(String, Vec<String>)>,
    ) -> Self {
        Highlighter {
            enable,
            disable,
            disable_builtins,
            custom_highlights,
        }
    }

    fn should_enable(&self, name: &str) -> bool {
        if let Some(ref enabled) = self.enable {
            enabled.contains(name)
        } else if let Some(ref disabled) = self.disable {
            !disabled.contains(name)
        } else {
            true
        }
    }

    fn highlight_line(&self, line: &str) -> String {
        let mut result = String::new();
        let mut i = 0;
        let bytes = line.as_bytes();

        while i < bytes.len() {
            // Try patterns in order
            if let Some((end, highlighted)) = self.try_complex_pattern(line, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            if let Some((end, highlighted)) = self.try_keyword(line, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            if let Some((end, highlighted)) = self.try_bracket(line, i) {
                result.push_str(&highlighted);
                i = end;
                continue;
            }

            // Default: just add the character
            result.push(bytes[i] as char);
            i += 1;
        }

        result
    }

    fn try_complex_pattern(&self, line: &str, pos: usize) -> Option<(usize, String)> {
        let remaining = &line[pos..];

        // Try UUID
        if self.should_enable("uuids") && remaining.len() >= 36 && is_uuid_pattern(&remaining[..36]) {
            return Some((pos + 36, self.highlight_uuid(&remaining[..36])));
        }

        // Try IPv4
        if self.should_enable("ip-addresses") {
            if let Some((len, addr)) = self.find_ipv4(remaining) {
                return Some((pos + len, self.highlight_ipv4(&addr)));
            }
        }

        // Try date (YYYY-MM-DD or YYYY/MM/DD)
        if self.should_enable("dates") && remaining.len() >= 10 && is_date_pattern(&remaining[..10]) {
            return Some((pos + 10, self.highlight_date(&remaining[..10])));
        }

        // Try time (HH:MM:SS or HH:MM with optional fractional seconds)
        if self.should_enable("dates") {
            if let Some((len, time_str)) = self.find_time(remaining) {
                return Some((pos + len, self.highlight_time(time_str)));
            }
        }

        // Try URL
        if self.should_enable("urls") {
            if let Some((len, url)) = self.find_url(remaining) {
                return Some((pos + len, self.highlight_url(&url)));
            }
        }

        // Try path
        if self.should_enable("paths") && remaining.starts_with('/') {
            if let Some((len, path)) = self.find_path(remaining) {
                return Some((pos + len, self.highlight_path(&path)));
            }
        }

        // Try quoted string
        if self.should_enable("quotes") && remaining.starts_with('"') {
            if let Some(end) = remaining[1..].find('"') {
                let quoted = &remaining[..end + 2];
                return Some((pos + end + 2, format!("\x1b[33m{}\x1b[0m", quoted)));
            }
        }

        None
    }

    fn try_keyword(&self, line: &str, pos: usize) -> Option<(usize, String)> {
        let remaining = &line[pos..];
        let at_word_boundary = pos == 0 || !line.as_bytes()[pos - 1].is_ascii_alphanumeric();

        if !at_word_boundary {
            return None;
        }

        // Log levels
        if !self.disable_builtins && self.should_enable("numbers") {
            if self.match_word(remaining, "ERROR") {
                return Some((pos + 5, "\x1b[31mERROR\x1b[0m".to_string()));
            }
            if self.match_word(remaining, "WARN") {
                return Some((pos + 4, "\x1b[33mWARN\x1b[0m".to_string()));
            }
            if self.match_word(remaining, "INFO") {
                return Some((pos + 4, "\x1b[37mINFO\x1b[0m".to_string()));
            }
            if self.match_word(remaining, "DEBUG") {
                return Some((pos + 5, "\x1b[32mDEBUG\x1b[0m".to_string()));
            }
            if self.match_word(remaining, "TRACE") {
                return Some((pos + 5, "\x1b[2mTRACE\x1b[0m".to_string()));
            }
        }

        // Boolean/null
        if !self.disable_builtins {
            if self.match_word(remaining, "true") {
                return Some((pos + 4, "\x1b[3;31mtrue\x1b[0m".to_string()));
            }
            if self.match_word(remaining, "false") {
                return Some((pos + 5, "\x1b[3;31mfalse\x1b[0m".to_string()));
            }
            if self.match_word(remaining, "null") {
                return Some((pos + 4, "\x1b[3;31mnull\x1b[0m".to_string()));
            }
        }

        // REST verbs with space
        if !self.disable_builtins {
            if remaining.starts_with(" GET ") {
                return Some((pos + 5, "\x1b[42;30m GET \x1b[0m".to_string()));
            }
            if remaining.starts_with(" POST ") {
                return Some((pos + 6, "\x1b[43;30m POST \x1b[0m".to_string()));
            }
            if remaining.starts_with(" PUT ") {
                return Some((pos + 5, "\x1b[45;30m PUT \x1b[0m".to_string()));
            }
            if remaining.starts_with(" DELETE ") {
                return Some((pos + 8, "\x1b[41;30m DELETE \x1b[0m".to_string()));
            }
            if remaining.starts_with(" PATCH ") {
                return Some((pos + 7, "\x1b[45;30m PATCH \x1b[0m".to_string()));
            }
        }

        // SUCCESS
        if !self.disable_builtins && self.match_word(remaining, "SUCCESS") {
            return Some((pos + 7, "\x1b[32mSUCCESS\x1b[0m".to_string()));
        }

        // Process names
        if self.should_enable("processes") {
            if let Some((len, name)) = self.find_process_name(remaining) {
                return Some((pos + len, format!("\x1b[33m{}\x1b[0m", name)));
            }
        }

        // Numbers
        if self.should_enable("numbers") && remaining.chars().next().map_or(false, |c| c.is_ascii_digit()) {
            if let Some((len, num)) = self.find_number(remaining) {
                return Some((pos + len, format!("\x1b[36m{}\x1b[0m", num)));
            }
        }

        // Custom highlights
        for (color, words) in &self.custom_highlights {
            let code = match color.as_str() {
                "red" => "\x1b[31m",
                "green" => "\x1b[32m",
                "yellow" => "\x1b[33m",
                "blue" => "\x1b[34m",
                "magenta" => "\x1b[35m",
                "cyan" => "\x1b[36m",
                _ => continue,
            };

            for word in words {
                if remaining.starts_with(word) && (word.len() >= remaining.len() || !remaining.as_bytes()[word.len()].is_ascii_alphanumeric()) {
                    return Some((pos + word.len(), format!("{}{}\x1b[0m", code, word)));
                }
            }
        }

        None
    }

    fn try_bracket(&self, line: &str, pos: usize) -> Option<(usize, String)> {
        let byte = line.as_bytes()[pos];
        if byte == b'[' || byte == b']' {
            return Some((pos + 1, format!("\x1b[31m{}\x1b[0m", byte as char)));
        }
        None
    }

    fn match_word(&self, text: &str, word: &str) -> bool {
        if !text.starts_with(word) {
            return false;
        }
        let after_pos = word.len();
        after_pos >= text.len() || !text.as_bytes()[after_pos].is_ascii_alphanumeric()
    }

    fn find_number(&self, text: &str) -> Option<(usize, String)> {
        let mut end = 0;
        for c in text.chars() {
            if c.is_ascii_digit() {
                end += c.len_utf8();
            } else {
                break;
            }
        }
        if end > 0 && (end >= text.len() || !text.as_bytes()[end].is_ascii_alphanumeric()) {
            Some((end, text[..end].to_string()))
        } else {
            None
        }
    }

    fn find_process_name(&self, text: &str) -> Option<(usize, String)> {
        let mut end = 0;
        for c in text.chars() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
                end += c.len_utf8();
            } else {
                break;
            }
        }
        if end > 0 && end < text.len() && (text.as_bytes()[end] == b'[' || text.as_bytes()[end] == b'(') {
            Some((end, text[..end].to_string()))
        } else {
            None
        }
    }

    fn find_time(&self, text: &str) -> Option<(usize, String)> {
        // HH:MM:SS.ffffff
        if text.len() >= 8 && is_time_hms(text) {
            let mut end = 8;
            if end < text.len() && text.as_bytes()[end] == b'.' {
                end += 1;
                while end < text.len() && text.as_bytes()[end].is_ascii_digit() {
                    end += 1;
                }
            }
            return Some((end, text[..end].to_string()));
        }

        // HH:MM
        if text.len() >= 5 && is_time_hm(text) {
            return Some((5, text[..5].to_string()));
        }

        None
    }

    fn find_url(&self, text: &str) -> Option<(usize, String)> {
        if let Some(pos) = text.find("://") {
            let scheme = &text[..pos];
            if scheme == "http" || scheme == "https" || scheme == "ftp" {
                let mut end = pos + 3;
                while end < text.len() && !text.as_bytes()[end].is_ascii_whitespace() {
                    end += 1;
                }
                return Some((end, text[..end].to_string()));
            }
        }
        None
    }

    fn find_path(&self, text: &str) -> Option<(usize, String)> {
        let mut end = 1;
        while end < text.len() && !text.as_bytes()[end].is_ascii_whitespace() {
            end += 1;
        }
        if end > 1 {
            Some((end, text[..end].to_string()))
        } else {
            None
        }
    }

    fn find_ipv4(&self, text: &str) -> Option<(usize, String)> {
        let mut i = 0;
        let mut parts = 0;
        let mut digit_count = 0;

        for (idx, &byte) in text.as_bytes().iter().enumerate() {
            if byte.is_ascii_digit() {
                digit_count += 1;
            } else if byte == b'.' {
                if digit_count > 0 {
                    parts += 1;
                    digit_count = 0;
                } else {
                    return None;
                }
            } else if digit_count > 0 {
                if parts == 3 {
                    let candidate = &text[..idx];
                    if is_ipv4_pattern(candidate) {
                        return Some((idx, candidate.to_string()));
                    }
                }
                return None;
            } else {
                return None;
            }
        }

        if digit_count > 0 && parts == 3 {
